package com.paybridge.fees;

public interface FeeStrategy {
    PaymentMethod method();
    Money fee(Payment payment);
}

@Component
class CardFee implements FeeStrategy {
    private final MerchantTierRepository tiers;
    CardFee(MerchantTierRepository tiers) { this.tiers = tiers; }
    public PaymentMethod method() { return PaymentMethod.CARD; }
    public Money fee(Payment p) {
        Money pct = p.amount().times(new BigDecimal("0.029"));
        return pct.plus(Money.of("0.30", p.currency())).max(tiers.minFee(p.merchantId(), p.currency()));
    }
}

