private final Map<PaymentMethod, FeeStrategy> strategies;

public FeeCalculator(List<FeeStrategy> all) {
  this.strategies = new EnumMap<>(PaymentMethod.class);
  for (FeeStrategy s : all) {
    if (strategies.put(s.method(), s) != null) throw new IllegalStateException("duplicate fee strategy for " + s.method());
  }
}

public Money calculate(Payment p) {
  FeeStrategy s = strategies.get(p.method());
  if (s == null) throw new UnsupportedPaymentMethodException(p.method());
  return s.fee(p);
}
